import{i as e}from"./xp-B-PqhZcT.js";import{v as t}from"./matchTime-plbU0zIc.js";var n=e=>String(e).replace(`.`,`,`),r=e,i=t.points,a=[{id:`xp`,term:`XP`,group:`Joueurs`,short:`Points d’expérience : chaque action du joueur en match rapporte ou retire des points.`,formula:`But +${r.goal} × multiplicateur adversaire (×${n(r.mult_top3)} contre un 1er–3e, ×${n(r.mult_4_6)} contre un 4e–6e, ×${n(r.mult_7plus)} ensuite) · passe décisive +${r.assist} (même multiplicateur) · victoire +${r.win} · défaite ${r.loss} · homme du match +${r.motm} · jaune ${r.yellow} · deux jaunes ${r.double_yellow_total} au total · rouge direct ${r.red_direct} · par match de suspension ${r.per_suspension_match} · gardien : clean sheet +${r.clean_sheet_gk}, arrêt +${r.save}, penalty arrêté +${r.penalty_saved}, tir au but arrêté +${r.shootout_saved}, but encaissé ${r.goal_conceded_gk} · joueur du mois +${r.player_of_month}, équipe du mois +${r.team_of_month}, but du mois +${r.goal_of_month}.`,example:`2 buts contre le 2e (2 × ${r.goal} × ${n(r.mult_top3)} = ${2*r.goal*r.mult_top3}) + 1 passe contre le 2e (${r.assist} × ${n(r.mult_top3)} = ${r.assist*r.mult_top3}) + victoire (${r.win}) + 1 jaune (${r.yellow}) = ${2*r.goal*r.mult_top3+r.assist*r.mult_top3+r.win+r.yellow} XP.`,note:`Barème par défaut ; l’admin peut l’ajuster pour une saison dans l’espace admin ; le site applique alors le barème de la saison.`},{id:`note`,term:`Note de match`,group:`Joueurs`,short:`Note sur 10 calculée à partir des actions du match (base 6,0).`,formula:`Total des actions : but +0,8 · passe +0,5 · victoire +0,4 / défaite −0,4 · homme du match +0,5 · jaune −0,4 · rouge −1,5 · gardien : arrêt +0,1, but encaissé −0,15, clean sheet +1,0. Si le total est positif : note = 6 + 4 × (1 − e^(−total / 3)), plafonnée à 9,9 ; sinon note = 6 + total, minimum 3,0.`,example:`1 but + 1 passe + victoire : total 1,7 → 6 + 4 × (1 − e^(−0,57)) = 7,7.`},{id:`ipg`,term:`IPG (Indice de Performance Globale)`,group:`IPG (saison 2025)`,short:`Indice sur 100 de la saison 2025 : le meilleur joueur vaut 100, les autres sont ramenés à cette échelle.`,formula:`IPG = IPG brut du joueur ÷ IPG brut le plus élevé × 100.`,example:`IPG brut 463,1 alors que le meilleur est à 568 → 463,1 ÷ 568 × 100 = 81,5.`,note:`Classement fourni par la ligue pour 2025 (fichier IPG Top 25). Il n’est pas encore calculé automatiquement pour 2026/27 : « – » tant qu’il n’est pas publié.`},{id:`ipg_brut`,term:`IPG brut`,group:`IPG (saison 2025)`,short:`Total de points avant la mise sur 100 de l’IPG.`,formula:`IPG brut = 3 × buts + 2 × passes + 2 × contribution (%) + victoires (%) − pénalité cartons + 2 × score gagnant + adversité (%), avec score gagnant = 3 × buts gagnants + passes gagnantes.`,example:`64 buts, 34 passes, contribution 57,6 %, victoires 72,2 %, pénalité 4, 13 buts et 11 passes gagnants (score 50), adversité 24,5 % : 192 + 68 + 115,2 + 72,2 − 4 + 100 + 24,5 = 567,9 ≈ 568.`,note:`Formule reconstituée à partir des colonnes du fichier 2025 de la ligue (elle retrouve l’IPG brut publié à ±2 points près) ; à confirmer par Ardentia.`},{id:`buts_passes`,term:`Buts / passes`,group:`IPG (saison 2025)`,short:`Buts marqués et passes décisives du joueur sur la saison.`},{id:`contribution`,term:`Contribution aux buts`,group:`IPG (saison 2025)`,short:`Part des buts de son équipe auxquels le joueur a participé (but ou passe décisive).`,formula:`Contribution = (buts + passes) ÷ buts marqués par l’équipe × 100.`,example:`20 buts + 10 passes dans une équipe qui a marqué 60 buts → 50 %.`},{id:`victoires`,term:`Victoires de l’équipe`,group:`IPG (saison 2025)`,short:`Pourcentage de matchs gagnés par l’équipe du joueur.`,formula:`Victoires = matchs gagnés ÷ matchs joués × 100.`,example:`13 victoires en 18 matchs → 72,2 %.`},{id:`gagnants`,term:`Buts / passes gagnants`,group:`IPG (saison 2025)`,short:`Buts et passes qui ont fait gagner ou arracher le nul à l’équipe (sans eux, le résultat aurait été moins bon).`,formula:`Score gagnant = 3 × buts gagnants + passes gagnantes (compté 2 fois dans l’IPG brut).`,example:`13 buts gagnants et 11 passes gagnantes → 3 × 13 + 11 = 50.`},{id:`adversite`,term:`Adversité`,group:`IPG (saison 2025)`,short:`Indicateur en % de la difficulté des matchs dans lesquels le joueur a été décisif.`,note:`Valeur reprise telle quelle du fichier IPG 2025 de la ligue : sa méthode de calcul n’y est pas détaillée.`},{id:`penalite_cartons`,term:`Pénalité cartons`,group:`IPG (saison 2025)`,short:`Points retirés à l’IPG brut pour les cartons reçus.`,note:`Valeur reprise telle quelle du fichier IPG 2025 de la ligue.`},{id:`points`,term:`Points (classement)`,group:`Équipes et classements`,short:`Victoire ${i.win} points, nul ${i.draw}, défaite ${i.loss} (art. ${i.art} du règlement).`,example:`4 victoires, 1 nul, 1 défaite → 4 × ${i.win} + ${i.draw} = ${4*i.win+i.draw} points.`},{id:`diff`,term:`Diff. (différence de buts)`,group:`Équipes et classements`,short:`Buts marqués moins buts encaissés.`,formula:`Diff. = buts pour − buts contre.`,example:`32 marqués, 20 encaissés → +12.`},{id:`force`,term:`Force des adversaires`,group:`Équipes et classements`,short:`Pré-saison : total des points actuels des équipes déjà rencontrées. Plus il est élevé, plus le parcours a été difficile.`,formula:`Force = somme des points des adversaires affrontés.`,example:`Adversaires à 9, 6, 3 et 0 points → force 18.`,note:`Sert à départager en fin de pré-saison, après points, différence et buts marqués.`},{id:`clean_sheet`,term:`Clean Sheet`,group:`Joueurs`,short:`Match terminé sans encaisser de but, pour le gardien qui a joué le match complet.`,example:`Rapporte +${r.clean_sheet_gk} XP et +1,0 à la note du gardien.`},{id:`badges`,term:`Badges`,group:`Badges`,short:`Récompenses débloquées par les actions du joueur pendant la saison (pré-saison incluse, Match des capitaines exclu).`,note:`La liste complète, avec la condition exacte de chaque badge, est plus bas et sur la page Badges.`},{id:`rarete`,term:`Rareté des badges`,group:`Badges`,short:`Commun (bronze), Rare (saphir), Épique (améthyste), Légendaire (or) : plus la condition est difficile, plus le badge est rare.`},{id:`niveaux`,term:`Platinum / Gold / Silver`,group:`Équipes et classements`,short:`Niveau d’ancienneté de l’équipe dans la ligue : Silver 1 saison, Gold 2 saisons, Platinum 3 saisons ou plus.`,note:`Calculé à partir des saisons jouées ; Ardentia peut corriger le nombre de saisons d’un club (modification journalisée).`},{id:`recrue`,term:`Recrue`,group:`Joueurs`,short:`Joueur dans sa première saison MBL, dans une équipe qui joue elle aussi sa première saison (ou marqué « Recrue » par l’admin).`}],o=new Map(a.map(e=>[e.id,e])),s=e=>o.get(e);export{s as n,a as t};